mapper.select:
select j.*, p.name platform_name, c.name channel_name, IFNULL(c.pay_rate, j.platform_rate) pay_rate from (



	 and update_time  >=  '${downLoadDate[0]}'
	 and update_time  <=  '${downLoadDate[1]}'

		and money  >=  #{priceMin}
		and money  <=  #{priceMax}


) j
left join pay_platform_new p on j.platform_id = p.id
left join pay_channel_new c on j.channel_id = c.id
order by update_time desc

select j.*, p.name platform_name, c.name channel_name, IFNULL(c.pay_rate, j.platform_rate) pay_rate from (

where id = #{id}
) j
left join pay_platform_new p on j.platform_id = p.id
left join pay_channel_new c on j.channel_id = c.id

SELECT p.name AS platformName,IFNULL(c.pay_rate,t.platform_rate) as channelPayRate,c.name AS channelName, t.platform_id as platformId ,t.channel_id as channelId,SUM( money ) AS money,SUM( sub_money ) AS subMoney ,t.update_time as updateTime FROM member_pay_jour t LEFT JOIN pay_channel_new c ON t.channel_id = c.id LEFT JOIN pay_platform_new p ON t.platform_id = p.id where t.status='1'
and t.platform_id = #{platformId}
and t.update_time >= #{selectStartDate} and t.update_time <= #{selectEndDate}
and t.channel_id in (SELECT id from pay_channel_new where name like concat(#{channelName}, '%'))
GROUP BY t.channel_id,t.platform_id

SELECT SUM( t.sub_money ) AS subMoney ,SUM(t.sub_money * IFNULL(c.pay_rate,t.platform_rate) ) AS handlingfeeTotal ,t.platform_id,t.channel_id,t.update_time,COUNT(*) AS totalcount
FROM member_pay_jour t LEFT JOIN pay_channel_new c ON t.channel_id = c.id
WHERE t.STATUS='1'

	and t.platform_id = #{platformId}


	and t.update_time  >=  #{selectStartDate} and t.update_time  <=  #{selectEndDate}


	and t.channel_id in (SELECT id from pay_channel_new where name like concat(#{channelName}, '%'))
